// STAND_INS: label -> what and why.
export const STAND_INS = {
  "H-UIIN": "act_tsk(84): UI_IN (entry 0x5014b736) is started by the harness; then one push of every group's idle image (S-KEYBITS)",
  "H-UIINRING": "the ring init 0x5014cb5f (ring pointers 0xa32dab9c/0xa32daba0 = 0xa32dab54) before H-UIIN, the one call of UI_IN's module init 0x5014bf91 (at 0x5014bf9e) the ring needs; the rest of that init does not run (its other stores write the BSS value 0; 0x5014e3ab, 0x5014ce00, 0x5005d36a, 0x5014d62e, 0x5014d97a are not traced; 0x5014d49e sets group 4's image 0x629887e4 and old state to the polarity bits, D, and does not run: both stay 0)",
  "S-KEYBITS": "the producers of UI_IN's raw key bits (SCPU RX, the poller) are not traced: the harness pushes a whole group image of groups 0..3 (1..3 on a body with H-SCPUPORT) with the firmware's push 0x5014cb74 and sets UI_IN's flag (set_flg); group 4 goes through the firmware's own producer (H-G4SET) after the idle push. Idle image: a type-2 key released (bit != polarity), a switch bit 0 (the old state of every lab before M10), the monitor bit 1 (\"not closed\", C2) and the mode dial one-hot at index 0 (the index-to-mode map is ?); on a ported body the power lever on and the USB connection 0x0400 with no cable, by their states (play.mjs IDLE_SWITCH_STATES), but in the group the firmware's group-4 producer pushes: the E143 family keeps 0x0400 at state 0",
  "H-SCPUIRQ": "(a body with the SCPU's port path) what the SCPU init, which does not run, does for its event word: the ports at the idle levels, their events cleared as the init clears them (127 to the event word 0x98), and IRQ 320 attached at level 5 to the init's handler through the firmware's attach; the handler then runs natively (docs/hle-gaps.md 4.7.2)",
  "H-UIINPORT": "(a body with the SCPU's port path) UI_IN's IRQ 320 callback registered through the firmware's registration, as UI_IN's port init (not run) registers it, and group 0's old state set from the port byte by the firmware's init that UI_IN's start stage (not run) calls first, so the idle levels decode nothing; any later registration of another callback is refused (PER_SCPU registers its own natively at its start, H-SCPUSTART, before UI_IN's)",
  "H-SCPUPORT": "(a body with the SCPU's port path) group 0 (power lever, Fn lever, S1, 0x1229, and the SCPU's three request lines, held high) is the SCPU interface's port levels (bit 31 of the window's port word 0xa0 + 4k), set through the lab's doorbell: each changed port sets its event bit, IRQ 320 is taken natively at the idle point, and its handler and UI_IN's callback push the port byte and set UI_IN's flag (iset_flg) natively. That a level change of either direction sets the event bit is I",
  "H-GIOSLOTS": "the reset of the GIO interrupt slots that the GIO init, which does not run, ends with, natively: with --hdmi on before the display init, which then registers the HDMI hot-plug pin's handler and attaches its group's IRQ 109 natively (docs/hle-gaps.md 4.9); else at the sub-CPU link's start (H-SCPUSTART), so that PER_SCPU's registration of pin 102 takes a slot and attaches IRQ 119 natively",
  "S-HDMISINK": "(--hdmi on) the sink an hdmi plug input puts on the port: a 1080p60 monitor's EDID (base block and a CTA-861 extension) composed for the lab, not captured from a monitor (src/lab/edid.mjs). The hot-plug pin's interrupt, the transmitter's start, the E-DDC reads with IRQ 239, the EDID's checks and parse and the report to UI_IN run natively",
  "A-HDMI-1": "(--hdmi on) the hot-plug pin's GIO status bit is set when the pin rises; nothing is set when it falls, and an unplug is refused: what the transmitter and the pin show when the cable comes out is not read",
  "H-FILEINIT": "(a body with the file system, src/fw/models.mjs card_fs) the file system's bring-up natively in the boot task's place, before the application starts: its queues and semaphores, logsec's and the SD host's init, the file layer (reading its NAND area through S-FSNAND), the card driver's detect states, and FILEFGND and DCFPROC_SUB started (docs/hle-gaps.md 4.8)",
  "H-FILECLBK": "(a body with the file system) FILECLBK, the file module's task, started with act_tsk after H-FILEINIT (the boot's start of it is not traced); the application's requests to the file module's queue then go to it (S-MODACK leaves them)",
  "S-SDHOST": "(a body with the file system) the SD host's registers: both ports' pages and the GPIO page of the card's pins and power are lab-stub pages that keep what the firmware writes, and SD_INFO2's clock-divider bit reads set, the one bit the host's set-up polls (I: TMIO's SCLKDIVEN). No SD interrupt is raised: the UHS-II PHY's link-up wait runs out (about 120 ms of lab time), as with a card without UHS-II, and the firmware falls back to the SD interface",
  "S-SDCARD": "(a body with the file system) an 8 GiB SDHC card, or a card of the host's size (OM_EMU_CARD_SIZE; above 32 GiB an SDXC card) (src/lab/sdcard.mjs; its registers the SD specification's, its values the lab's choice) at the firmware's SD command layer: each command is answered there with its response, data and status and its completion called at once, as the layer does for a busy port. sd_mount's card init, sdmem's transfers, the format and the FAT / DCF layers above run natively; the card starts blank (or as the host kept it, OM_EMU_CARD) and the firmware formats it itself. Out of the slot (the input card remove) it answers no command, as an empty slot; it goes back in (card insert) with its sectors as they were, in its idle state",
  "S-SDPOWER": "(a body with the file system whose SD driver asks a power manager for the card's supply: the E144 family's E144, E137, E142, E140, E125, E130, X) the request's synchronous send, to a power manager the lab does not run, is answered 0; a request that returns before its send (E143's, E146's, E147's, E139's) never meets it",
  "S-SDSWITCH": "(a body with the file system whose SD driver switches a card line through its sub-CPU: E118, X) the driver's request, which goes out over the sub-CPU's serial link the lab does not model, is answered at its send: its callback is called with status 0 and the send returns 0, where the driver would otherwise poll for the sub-CPU's answer for good (E122 and E120 set a GIO pin instead)",
  "S-FSNAND": "(a body with the file system) the file system's NAND area (512 KiB of flash) behind the NAND access: it reads erased (0xff), a camera that never saved it, and the firmware's writes are kept for the session; the lab's NAND is not modelled",
  "S-ALBM": "(a body with the file system) the album manager's per-drive init, which the DCF numbering mount calls, returns at once: ALBM_MAIN, which it would start, allocates its first request's id with udf07 (docs/om1-udf-spec.md row 14, kept faulting), and the movie module it asks does not run",
  "S-RECFILE": "(a body with the file system) the picture's file at a release's END_SHOOTING_PICTURE, in place of REC_FILE (the recording modules do not run): the file module's own file requests (mkdir, fopen 'wb', fwrite, fclose, as the FlashAir configuration writer makes them) write a JPEG the lab encodes (src/lab/jpeg.mjs: S-SCENE's frame at the capture with each 8 x 8 block its mean, black without the live view; no EXIF) at the DCF name the numbering mount gave (C:\\DCIM\\100OMSYS\\P1010001.JPG and on; the DCF module's initial names, the camera's carry its clock's month and day, I). The DCF database is not told: the firmware counts the file from the next mount (its DCF numbering mount and its image count find it, X)",
  "S-MDACTRL": "(a body with the file system and its HLS side: E143, E146) the function component's part of a Card Formatting from the menu (CmpCst_Function, an HLS component that does not run): at the media control's start (TRA 1511, command 1, which S-TRAACK answers) api_media's format runs natively, so the file module formats the card from the firmware's own request; the file module's progress events become the component's progress notifications (1513, its own percent) and its reply the component's end: the slots' format flags, 1513 at 100, 697 and the result 1514 (kind 72), which takes the application from Busy back to the menu (E143's ids; E146's request, progress and result are 1509, 1511 and 1512); before the result the DCF numbering mount again, for the next file number (I). The notifications are the firmware's own event objects through the reception's synchronous slot (the component's asynchronous one needs the OXF main thread, which does not run, I). Any other media control command or an error status stops the session (docs/hle-gaps.md 4.8.3)",
  "S-MEDIA": "(a body with the file system and its HLS side: E143, E146) the media manager's part of a card's removal and insertion (CapMed_MediaManager, an HLS component that does not run): the card switch changes as a body's does (UI_IN decodes it natively and calls the file layer's own callback); on its event the stand-in reads the switch's level natively and, for a card out (level 1, I), sets the slot's HLS mount state to unmounted with the firmware's setter, sends the DCF process's card out and the sdmem card-info clear (I: its sender is not read) and the notification 711 {kind, 0, 0}; for a card in, 711 {kind, 1, 0}, S-CARD's insertion requests, the mount state mounted and 711 {kind, 1, 2} and {kind, 1, 8}. The application's media control turns them into its card-out, card-in and mount events natively; which notifications the manager sends, and in which order, is I (docs/hle-gaps.md 4.8.3)",
  "H-DPCINIT": "(a board with the deferred-call triggers, src/fw/board.mjs dpc) the deferred-call init (the boot head's, not run by the lab; E143 0x50050279, src/fw/facts.mjs deferredCalls) natively at the play bring-up, or with the native lens (src/fw/models.mjs lens_native) before the lens init: the six rings cleared, the six trigger words written 0 and their IRQs attached (E143 53..58, the E144 family 29..34); a post (the lens's power and detect paths, E132's first serial request) writes 1 to its trigger word (src/dev/dpc.mjs), which raises the IRQ, taken at the next idle point",
  "H-LENSINIT": "(a body with the native lens: E143, E146, E147; the body's addresses read by src/fw/facts.mjs lensDriver, E143's here) the lens module init 0x502a5d10 (boot call 0x50024ab6), then USTART_L's lens data cache load 0x502a6371 and lens task variables 0x502a5dff natively before the application starts, the cache load after the module init (I: the init clears the cache's ready byte the load sets and the lens start waits on), and LENS_MAIN, LENS_COMMAND and LENS_ASKDATA started with act_tsk",
  "S-LENSNAND": "(a body with the native lens) the lens data caches' NAND (7 areas of 256 KiB from 0x416e0000, E143's flash area table 0x602a4a24; the body's read by src/fw/facts.mjs lensDriver) behind the NAND access the card's S-FSNAND serves: it reads erased, a camera that never cached a lens, and a read of no bytes (the lens tables' flash area, whose extent the flash area init, not run, would set) reads nothing",
  "H-LENSON": "(a body with the native lens) TAKE_FUNC's request to LENS_EXEC at the camera's start (command 1, 0x502cd9c7..0x502cd9f2), posted by the lab with no reply queue (TAKE_FUNC, which would take the reply, does not run); LENS_MAIN's camera-on then runs the lens's detect, power-on and start natively, with the lens on the mount: its detect pin low and the lock pin switch LLPSW (0x121c) released in the idle image (its bit the body's UI_IN tables')",
  "S-LENSMCU": "(a body with the native lens) the lens's microcontroller at the far end of the lens serial controller (src/lab/lensmcu.mjs): the frames of the lens's start and its state poll answered in the layouts their parsers read (docs/hle-gaps.md 4.4.2), the values of the 12-40mm F2.8 PRO S-LENS wrote (its ID, name, zoom steps' focal lengths, apertures; I), the zoom step S-SCENE's focal length; a frame it does not know stops the session naming it",
  "A-LENSSSC-1": "(a body with the native lens) a lens frame is sent and answered at once, in zero lab time: the controller's interrupt is taken at the next idle point",
  "A-LENSMCU-1": "(a body with the native lens) the lens's fields the lab has no value for are 0: its flags (no optional functions), function words, tables beyond the characteristics S-LENS wrote, serial number and firmware version",
  "A-LENSMCU-2": "(a body with the native lens) the lens reports the protocol version 0x130a, the newest the driver tests for, with no block mode; the 12-40's own is ?",
  "A-LENSMCU-3": "(a body with the native lens) one byte a zoom step in the table of id 71 (the driver logs a reply of class 0xcx with no data as an error)",
  "A-DPC-1": "(a board with the deferred-call triggers) bit 0 of a deferred-call trigger word is its IRQ's level: high until the word is written 0 or, for the first two IRQs (E143 53 and 54), until their handler disables the IRQ (the next post enables it again)",
  "H-ACCINIT": "(a body with the accelerometer, src/fw/models.mjs acc) the ACC module init natively in the boot's place, before the application starts: its pointers, the axis references, the temperature and offset parameters from the store, and ACC_MAIN (task 121) started; its device part (the sensor's data-ready pin and the register API's kernel objects) is stepped over. ACC_MAIN then runs natively: the probe once, every 80 ms the cache copy and the correction (docs/hle-gaps.md 4.7.3)",
  "S-ACCREG": "(a body with the accelerometer) the sensor's register file at its register API (open, read, write, close): the probe's WHO_AM_I read answered with the value the probe wants and its two set-up writes kept; any other access stops the session (the sample reads go through ACC_SENS_MAIN, which does not run)",
  "S-ACCSAMPLE": "(a body with the accelerometer) the sensor, its data-ready pin, the sampler task ACC_SENS_MAIN and its transfer: before each of ACC_MAIN's cache copies, one new sample stored as the read's completion stores it (the accelerometer's three halfwords and the temperature word, the counter + 1). The sample is the firmware's pose-0 reference for the level camera, turned by the session's tilt input (roll, pitch in degrees)",
  "H-SLOPEINIT": "(a body with the accelerometer) PER_SLOPE's init natively before the application starts: its flag, its state and task 78 started; the GUI's startLevel then runs it natively (every 20 ms the remap, mg, the asin table, the stability test, the results the gauge's getter reads and its event to the application)",
  "A-ACC-1": "(a body with the accelerometer) the sensor reads 25.0 degC (the temperature word 0); the temperature compensation is off on the lab's blank factory data anyway (calibration type 255)",
  "A-ACC-2": "(a body with the accelerometer) one new sample per ACC_MAIN cycle (80 ms; the probe's CTRL1_XL write 0x10 is 12.5 Hz by ST's register map, I), and only tilts that keep the body's y axis dominant (roll and pitch within 45 degrees): PER_ROTATE, which would turn the camera's orientation, does not run, so the orientation stays 0",
  "A-ACC-3": "(a body with the accelerometer) the tilt input's roll is the angle the gauge's getter reads back as its horizon, its pitch three times the getter's vertical (the getter divides by 3, D); which physical direction each sign is has no camera evidence",
  "H-G4SET": "a group-4 input (HDMI, CEC keys, lens key, lens MF, 0x0400, grip 0x2003) is the firmware's own group-4 producer 0x5014d537(code, 0 = bit at its polarity / 1 = the other level) called from the lab task (its callers, e.g. the display driver's HDMI report 0x501d69d8, do not run, but for that report with --hdmi on, where fw_0501 is refused): it keeps UI_IN's own image 0x629887e4, which UI_IN's LLPSW branch also pushes (0x5014c9a4), so group 4 has one image",
  "H-DIALSTEP": "a dial detent is one call of the firmware's counter writer 0x5014bae6(dial id, +1 or -1) from the lab task (its callers, the command dispatcher 0x5100af66 and the encoder reader 0x5014bd60 whose position read 0x50059fa4 is not modelled, do not run); UI_IN's dial step then posts the dial id natively. A detent whose counter word the GUI does not read is reported (dial_unread) and the word cleared",
  "H-JSINJECT": "the multi-selector is UI_IN's code entry 0x5014c12e from the lab task: the press 0x1235 (0 press / 1 release), the directions 0x1234 (0..7, 8 centre; one direction at a time, a second one through the centre). The raw producer of 0x1234/0x1235 is ?; the decoder, the post and the application's direction query run natively",
  "H-TOUCHGAP": "touch samples are served at least 20 ms of lab time after the previous one ended: the driver queues gestures for 10 ms after a PRESS into 5 unchecked slots (0x501e487b..b2, timer 0x501e48c2..df) and three taps with no lab time between them overrun it (fault at 0x501e4a13, X). With --idle wall also at least the user's gap after the lab time the previous sample ran at (the page's timestamps, else arrival times): inside one contact up to 2 s, from a lift to the next down up to 0.32 s. The driver takes a second tap 287.0 ms after the lift as DCLICK and 300.3 ms after it as CLICK (X; where it keeps the window is ?), so a separate tap stays a tap and a double tap stays one; a tap costs at most 0.32 s of lab time more than its hold. The touch controller's report rate is ?",
  "S-DISPQ": "the display manager's asynchronous DISPLAY request (OlyQeWr to the DISPLAY queue 0x88 from 0x503eba00, DISPLAY cmd 18 on every shooting-screen transition, X) runs the DISPLAY loop 0x501c3035 at once, as the synchronous sends do (the DISPLAY task, static id 54, priority 26, outranks the GUI and does not run as a task in the labs); the loop's replies to queue 6 (0x501c48bf, OlyQeWr at 0x501c490c / 0x501c496d, returning to 0x501c4913 / 0x501c4974), whose reader, the camera application's task 58, does not run, are recorded and return E_OK. Without it the queue fills and the 30th request blocks the GUI for good (X). Any other send to the DISPLAY queue is an error",
  "S-BGDRAW": "0x50b3dcca returns d0 = 0 to two GUI callers (return addresses 0x510c9a07: shooting screen, direct WB / Picture Mode, dial-direct; 0x510c9cf5: playback), whose paint stays held without it; its other callers (menu entry, menu close) run it natively as every other lab does",
  "S-CAFWD": "(with S-LENS, where the camera application's touch path is off) the GUI's touch forward to the camera (CA caller vt+4 0x51084994 with event 35) is recorded and returns d0 = 0 without calling (this+212) vt+8; every other event runs natively. With the native lens the application forwards the touches and takes this answer itself (docs/hle-gaps.md 4.4.2)",
  "S-TOUCHMAP": "(with S-LENS) camera-application stand-in: HFW touch status -> GUI touch kind by name (225 TOUCH 1, 226 LONG 2, 227 RELEASE 3, 228 TAP 4, 230 DOUBLE TAP 5, 229 SLIDE 6, 300 FLICK -> 7, I), posted as index 109; with the native lens the application posts them itself",
  "H-TPINIT": "the boot call of touch init 0x501e3dca (from 0x50024ca6) from the lab task, then act_tsk(83)",
  "H-TPSTART": "TP_OPEN 0x501e40da(HFW callback 0x60b97e80, 0) and the gesture mask 0x501e41d1(0x11f1) from the lab task (the camera application's own start call is not traced)",
  "S-TPREG": "the touch controller read 0x501e4f2a serves slave 0x70 from register 0x02 out of an 11-byte image: count, event<<6|x>>8, x, id<<4|y>>8, y, 0, 0, then the second point as event 3 / 0xfff (no point, the executed probes' bytes); raw = (x, 599 - y), the driver's flip 0x501e44c0 reports (x, y)",
  "S-TPINT": "the touch interrupt: OlyEvSt(touch flag, 1) from the lab task, what the pin-110 callback 0x501e5233 does with iOlyEvSt",
  "S-GPIO-TP": "lab-stub page 0x9b880000 opened; pins 48, 49, 108 (0x9b880e00, 0x9b880e40, 0x9b883e80, table 0x60025ff8) read level 1 (bit 4), the only level at which the driver accepts a touch (0x501e4858..79, 0x501e4bbb..df); what the pins are is ?",
  "A-USLAB": "channel 33 (the us clock) counts lab microseconds plus one per CPU read (timer window USMODE = 1): one count = 1 us (A-TMR-2)",
  "H-POWER": "the power lever's off is decoded natively (UI_IN's group 0 through the SCPU's ports, H-SCPUPORT) and the application takes its code; on a body that runs its power-off (E143, E146, E147: src/fw/models.mjs power_native, at the addresses src/fw/facts.mjs powerOff reads) the lab then runs the firmware's own power-off from the HFW's shutDown (S-SHUTDOWN, src/lab/power.mjs) and ends the session at its last write, 127 into the SCPU window's request word, after the sub-CPU's 0x85 power-off; elsewhere it closes the session at once. On brings up a new one; the camera's power-on sequence is not run",
  "H-DRVINIT": "(a body whose reset path runs a table of early driver inits, src/fw/models.mjs boot_drivers: the E118 family's) the table natively at the start of the timer boot steps, which the lab, entering at the kernel, would skip: the GIO pins' configuration and the board-id read (into the lab stub's pages), and the timer pool the software-timer init allocates from",
  "H-MMINIT": "(a body whose boot chain calls a module init of its own at stage 3, src/fw/facts.mjs mmInit: the E118 family's) that init natively after the memory managers' constructors, which the lab, ending the init task, would skip: on E122 two slot managers whose methods the application's property reads reach",
  "A-PERIOD": "(a body whose vtotal functions return constants with no frame period getter after them, src/fw/models.mjs frame_period_us: the E118 family's) the TFT's and the EVF's frame period, which the build keeps nowhere the lab can read, is assumed: E143's TFT period of 16683 us. It sets only the lab clock's line time",
  "H-PWRTASK": "(a body with the power task, src/fw/facts.mjs powerTask) the power task, which the boot starts, started with act_tsk at the play bring-up: it runs the power module's init, the internal charger's with it (its IIC channel's configuration and completion flag), and waits on its queue",
  "H-SIOMAP": "(a body with PER_SIO devices, src/fw/models.mjs sio_devices: E129, E132) PER_SIO's channel map set at the play bring-up by the firmware's own setter (src/fw/facts.mjs sioDriver map_init), the end of PER_SIO's channel init, which the boot runs and the lab does not: each channel then reaches its own serial controller (on the TG-5s channel 9 index 7, the panel's channel 2 index 2 and the IIC bus's channel 3 index 3, their register blocks lab-stub pages that keep what is written, src/fw/models.mjs board stub_pages); before, every channel's index was read from low memory, and the channels shared one controller's open flag (D)",
  "S-SIOIIC": "(a body with PER_SIO devices) PER_SIO's serial controller for the channels a device sits on, at its driver's transfer and receive starts (src/lab/sio.mjs, src/fw/facts.mjs sioDriver): PER_SIO's IIC layer and the driver's completion dispatch run natively; a transfer's bytes are split at the transfer's restart list into IIC segments, each opened by its address byte, and handed to the device (writes, and a last read of the kept receive's count); the transfer ends at the MN's next idle point (A-SIOIIC-1) in interrupt context: the restart list cleared, the transfer's then the receive's completion dispatched with status 0, the received bytes written first. A polled transfer, a read segment not last or carrying data, a receive without a read stop the session; the other channels' starts run natively",
  "A-SIOIIC-1": "(a body with PER_SIO devices) a transfer on a served channel takes no bus time: it ends at the MN's next idle point (the TG-5 charger's 3 bytes at 400 kHz take about 70 us on the bus)",
  "S-CHARGER": "(E129, E132) the TG-5's internal charger at address 0x1b on PER_SIO's channel 9 (src/lab/charger.mjs): registers 0, 1 and 2, the ones the charger request's table writes, keep what is written (I: the request reads each write back and compares), a read answers the register the write segment before it named; a read of a register not written in the session (its value on the camera is ?), another address, register or length stops the session. The chip is not named in the image (?)",
  "H-UIOUTSTART": "(a body with MODELS ui_out: E134) UI_OUT, the module of the camera's lamps, which the boot starts: its init natively at the play bring-up, then act_tsk of its static task, which waits on its queue and takes the lamps' requests natively; the file layer's card access lamp requests (sends without a timeout to that queue) then go through",
  "S-BOOTKEY": "UI_IN's boot key (src/fw/facts.mjs bootState), which its module init records from the sub-CPU's wake factor (not run: H-UIINRING), is the power switch's code 0x000c, set before UI_IN starts: the camera started by its power lever or button, which the camera application's wake-up judgement takes for API_WUI_POWER_BUTTON (D); at 0 it took a battery insertion, and E133 started the boot service that creates no GUI (X; docs/model-survey.md)",
  "S-BOOTSTAGE": "the boot's first stage readied: bit 0 of the stages' ready word (src/fw/facts.mjs bootState) set before the settings store's start, as the boot's stage step for stage 1, which the lab does not run, would set it; the image holds every stage's code, the step's other work is not done and the later stages stay unset. E129's settings flash read waits for it (D; docs/model-survey.md)",
  "S-SHUTDOWN": "(E143, E146, E147) the HLS camera-common component (CmpCCom_CameraCommonComponent), which turns the lever's EV_POWER_SW_OFF into the shutdown, is not created in the lab: the lab calls the HFW's CameraCommon object's shutDown(API_SHUTDOWN_NORMAL, API_SHUTDOWN_REASON_BUTTON) through its vtable, as the shell's \"sdk api shutdown\" does, on the lab task in lab time; from there the firmware runs natively: OlyHfwPower's startShutDown, the settings' save, the RAM log's save, the file module's power-off, api_system's power-off sequence with the IO expanders' commands (none on E147), the SCPU window's ports and wake word, the sub-CPU's 0x85 {1} over the link, and 127 into the window's request word, where the session ends (docs/hle-gaps.md 4.7.4). That the lever's reason is BUTTON is I",
  "H-PWRSTART": "(E143, E146, E147) the power manager (PWR_MAIN) started natively at the play bring-up as the boot starter would start it: its init, which reads the sub-CPU's PC13 (0x82 {45}) and syncs with it (0x12 {5}, answered by the sub-CPU's message 0x12 {5}), then act_tsk of its static task; it then waits for its queue's messages",
  "S-IOEXP": "(E143, E146) the IO expanders' tasks (PER_IOEXP, PER_IOEXP_PBH) do not run (their PER_SIO channels and chips are not modelled): each request their APIs post is completed at the next idle point as the task would complete it, by its completion flag (a request without data) or the GIO extension's write's callback; what the expanders' pins do is not modelled, and any other request stops the session",
  "S-PWRLOG": "(E143, E146, E147) the power-off's save of its RAM log (2 MiB to its own NAND area) is answered done and not kept: the NAND controller is not modelled",
  "H-SCPUPOLL": "(E143, E146, E147) after its power-off 0x85 the MN polls pin 102 in a loop without an idle point until the sub-CPU drops it (it does as it leaves steady, D): at each poll the sub-CPU acts as at an idle point (I: on the camera it runs beside the MN)",
  "H-IDLE": "lab time runs in ELAPSE slices of at most 50 ms paced to the wall clock between inputs",
  "S-HEAP": "the malloc/free stand-ins (src/lab/hle.mjs) with reuse: free() puts a block on a per-size list that malloc() takes from first (the bump allocator of the other labs never reuses and runs out in a play session)",
  "SWITCH": "(M8, live since M10B) DISPLAY cmd 2 OPEN of the other device, H-RESEND (the display manager's palette request 0x503e52c7), H-EYESTATE, H-CONNECT; the camera application re-enters the screen (S-OUTDISP); play no longer runs H-UPDATE (the GUI's own repaint programs the new channel)",
  "S-TAKEOVER": "(M8, every play session since M10B) 0x50ab6299(9, 2) natively once at bring-up: module 9 state 2, the value API 70405 writes on the boot take-over path (0x501e6adb -> 0x50ab2309 -> 0x50adffda, D); no live switch writes it. Scope guard: module 9 may be read (0x50ab5780) only by ChangeOutline (0x50abcfd7 / 0x50abcfe2) for the whole session, any other reader is an error",
  "H-CONNECT": "(M8, generalised in M10B) sendEvent(131, lOutput) after every switch and at an EVF start: lOutput 2 TFT (the sender 0x5105053c's row for devices 2/3, D) and 7 EVF (its INTERNAL_EVF row for device 6, D; its EVF row for device 5 writes 3, whose handler sets connect state 3 and SetLayoutMode(0); which row the camera takes is not traced, 7 is chosen because its handler 0x510c6c27 sets connect state 5); that the camera sends it after the OPEN is an inference. Checked through the B2 observers: ConnectChangePlay ran, vt+20 returned 0 with no RPC, SetConnectState 2 / 5",
  "H-STOREFIRST": "(PLAYFIX, EVF starts only) harness order, not a firmware stand-in: an EVF start runs the settings store init before the EVF OPEN (MenuLab store_first, M8), closer to boot (settings spec section 4: the registry bootstrap follows the flash read at 0x500093ec). The OPEN registers the eye callback 0x501c6aca(1) -> 0x50050e67 -> 0x500515ed, which reads property 1947 (kind 0x4671): on the firmware's default 1 it deletes the timer; on the empty store it reads 0 and arms a 5000 ms one-shot (0x5005899c, callback 0x500516af) that, through task 16, dims the EVF OSD planes to level 32 (0x501c6a93, debug string \"[EVF] display_bievf_vsc_sio_send_brightness_yakitsuki\"), PLANC 0x40, outside the model (A7; X: every EVF frame failed from lab 5.6 s). TFT starts keep the store init after the OPEN: a store-first TFT OPEN sets CTRL3 bit 6 before play's A15 bracket recorder exists",
  "H-EYESTATE": "(M10B; every switch since fix3) the eye-state setter 0x50050efd(2 EVF / 1 TFT) natively from the lab task, the values the output selector 0x501e7fd8 reads (2 = EVF, 0x501e806c) and the key-script player 0x5100af70..88 passes (D; fix2: until then play passed them the other way round). Stand-in (I): play shows one display and its viewer looks at it, so after every switch, LV included, the eye state is the shown device's; a real LV press does not move the eye, and with property 1947 = 0 and nobody at the finder the EVF OPEN arms the 5 s burn-in one-shot, whose dim (PLANC 0x40) the model cannot draw (A7). The setter deletes that pending one-shot (0x50051658..71). A start leaves the state 0 (not yet sensed). Its publish 0x02022301 returns at the gate 0x5002509e ((0xa31f1d26) != 119), so it does not move the GUI",
  "A15": "(M10B, play only, --a15 auto) the composite may assume A15 when the shown channel's latched CTRL3 is exactly 0x41 and every 0x501e04b7(ch, 0) since the channel's last OPEN was closed by (ch, 1) at the same lab time, none open now; otherwise FEATURE_UNOBSERVED as in every check. CTRL3 bit 6's meaning is unknown",
  "H-AEINIT": "(M10B) the table init 0x50560b29 natively at bring-up (pre-condition: its regions still BSS 0); on the camera the boot sequence reaches it through 0x501e90c4 -> 0x50553649 -> 0x505724cc -> 0x50572574 (D), which the lab does not run. Without it a store write from the Super Control Panel or FUNC_DIRECT on Metering, Drive, ISO, Exposure Comp., Flash Mode or Flash Exposure Comp. faults in the interpolation 0x50563138 (div by zero at 0x5056319c). Its inputs are the F-store objects 420 / 403 (kinds 6730 / 6458), image templates of 0 because the lab has no flash data, so the interpolation returns 0",
  "H-IPIINIT": "(M10B) the inter-CPU init 0x5002ce4d (boot caller 0x5000032b) natively at bring-up: 0x5002de2d clears its 256 x 64 byte pool (pre-condition: still BSS 0), IRQ 324 attached at level 2 for CPUs 0..3 (handler 0x5002d83a for CPU 0) and enabled",
  "A-IPI": "(M10B, emu's model) the banks' +0x808 hold inter-CPU pending bits (a write ORs, a read returns them), +0x80c clears the written bits; bank 0's bits drive IRQ 324. Whether +0x808 ORs or overwrites cannot be observed while the firmware writes single bits",
  "S-CPU2": "(M10B) CPU 2 is not in the lab: when the GUI's post to CPU 2 (0x50aa9d4e) returns with exactly bank-2 bit 8 pending and one new ring [2][0] entry {0x60acb193, 0}, the stand-in acks the bit, drains the entry, does task 0x200e's command 3 (copy 28 bytes 0x62ee9408 -> 0xa33da484, (0xa33da778) -> 0xa33da49c) and posts CPU 2's reply as 0x50035afd(0, 0x60acbfb7, 0) would (ring [0][2], bank-0 bit 0x20); CPU 0 then takes IRQ 324 natively and the reply wakes the GUI. Anything else is an error, among it the swap path 0x50aaad0e taken when (0x62ee93e8) != 0. Task 0x200e is the audio sequencer (aud_seq strings, D) and the snapshot words are its level (peak) data (0x50aaab36..c8 keeps the maxima and increments 0x62ee93e8): lab RAM CPU 2 never wrote, so they read 0; on the camera the swap path is the usual one",
};

const hex4 = (v) => '0x' + v.toString(16).padStart(4, '0');
// /api/controls: each row with uiin as an object and the EV names and GUI message names the
// image's tables give (tables: play.mjs Tables of the image).
export function controlsDoc(tables) {
  return CONTROL_ROWS.map((c) => {
    const r = { ...c };
    if (c.uiin) {
      const [group, byte, bit, code, type, polarity] = c.uiin;
      r.uiin = { group, byte, bit, code: hex4(code), type, polarity };
      r.ev = (type === 2 ? [0, 1] : [2]).map((k) => tables.ev_name((k << 16 | 0x02000000 | code) >>> 0));
    } else if (c.dial) r.ev = [tables.ev_name(c.dial[0])];
    else if (c.js_ev) r.ev = [c.js_ev, tables.ev.get(JS_EV_CENTRE) ?? null];
    else if (c.inject) r.ev = [tables.ev_name((0x02000000 | c.inject[0]) >>> 0), tables.ev_name((0x02010000 | c.inject[0]) >>> 0)];
    r.gui_names = c.gui.map((i) => tables.index_name(i));
    return r;
  });
}
// /api/screens.
export function screensDoc() {
  return { not_offered: NOT_OFFERED, stand_ins: STAND_INS };
}
